import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.file.*;
import java.util.Base64;

public class Main {
    private static final String TARGET_MODEL = "qwen-audio-3.1-tts-flash";
    // 将 input.mp3 替换为本地待复刻的 MP3 音频文件。
    private static final String AUDIO_FILE = "input.mp3";

    public static String toDataUrl(String filePath) throws Exception {
        byte[] bytes = Files.readAllBytes(Paths.get(filePath));
        return "data:audio/mpeg;base64," + Base64.getEncoder().encodeToString(bytes);
    }

    public static void main(String[] args) {
        String apiKey = System.getenv("DASHSCOPE_API_KEY");
        String apiUrl = "https://[workspace-id].cn-beijing.maas.aliyuncs.com/api/v1/services/audio/tts/customization";
        try {
            JsonObject input = new JsonObject();
            input.addProperty("action", "create_voice");
            input.addProperty("target_model", TARGET_MODEL);
            input.addProperty("prefix", "guanyu");
            input.addProperty("audio", toDataUrl(AUDIO_FILE));
            JsonObject payload = new JsonObject();
            payload.addProperty("model", "voice-enrollment");
            payload.add("input", input);

            HttpURLConnection con = (HttpURLConnection) new URL(apiUrl).openConnection();
            con.setRequestMethod("POST");
            con.setRequestProperty("Authorization", "Bearer " + apiKey);
            con.setRequestProperty("Content-Type", "application/json");
            con.setDoOutput(true);
            try (OutputStream os = con.getOutputStream()) {
                os.write(payload.toString().getBytes("UTF-8"));
            }
            int status = con.getResponseCode();
            InputStream stream = status >= 200 && status < 300
                    ? con.getInputStream() : con.getErrorStream();
            StringBuilder response = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, "UTF-8"))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    response.append(line);
                }
            }
            System.out.println("HTTP status: " + status);
            System.out.println("Response is: " + response);
            if (status == 200) {
                JsonObject result = new Gson().fromJson(response.toString(), JsonObject.class);
                String voice = result.getAsJsonObject("output").get("voice_id").getAsString();
                System.out.println("voice name is: " + voice);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
